\label{def:SandS}
  For $n,J \in {\mathbb Z}_{>0}$, $\delta > 0,$ and $X_1,\dots,X_n \in {\mathbb R}_{>0}$  define the space of $J$ times differentiable dyadically supported functions. 
\begin{align*}
    C_\delta^J (X_1,\dots,X_n) := \{f\in& C^J({\mathbb R}^n): \, f(x_1,\dots,x_n) \,\, \text{supported on} \,  \\
    &(|x_1|,\dots,|x_n|) \in [X_1,2X_1] \times \cdots \times [X_n,2X_n], \\
    &  \|\partial_{x_1}^{J_1} \cdots \partial_{x_n}^{J_n} f\|_\infty \leq  \prod_{i \leq n} (\delta  X_i)^{-J_i} \quad \text{for all} \quad 0 \leq J_1+\cdots+J_n  \leq J  \}.
\end{align*}

\begin{align*}
    C_\delta^J (X_1,\dots,X_n) := \{f\in& C^J({\mathbb R}^n): \, f(x_1,\dots,x_n) \,\, \text{supported on} \,  \\
    &(|x_1|,\dots,|x_n|) \in [X_1,2X_1] \times \cdots \times [X_n,2X_n], \\
    &  \|\partial_{x_1}^{J_1} \cdots \partial_{x_n}^{J_n} f\|_\infty \leq  \prod_{i \leq n} (\delta  X_i)^{-J_i} \quad \text{for all} \quad 0 \leq J_1+\cdots+J_n  \leq J  \}.
\end{align*}

 \label{thm:mainblackbox}
Let $\mathcal{M} \subseteq \operatorname{SL}_2({\mathbb R})$,\, $q_1,q_2\in {\mathbb Z}_{>0}$ and denote $\Gamma = \Gamma_2(q_1,q_2)$. Let $\mathrm d g$ denote integration with respect to the Haar measure of the group $\operatorname{SL}_2({\mathbb R})$. Assume that $\mathcal{M}$ is left 
$\Gamma$-invariant with finitely many orbits $\Gamma \backslash \mathcal{M}$ and let $\alpha \in \mathcal{A}(\Gamma \backslash \mathcal{M})$.  Let $A,C,D,\delta > 0$  with $AD > \delta$ and let $f \in C^{7}_\delta (A,C,D)$. Denote $F:\operatorname{SL}_2({\mathbb R}) \to {\mathbb C}, \, F(\smqty(a & b \\ c& d)):= f(a,c,d)$. Then for any $\varepsilon > 0$ we have
\begin{align*}
   \bigg|  \sum_{g \in \mathcal{M}}  \alpha(g) F(g)  -  \frac{1}{|\Gamma \backslash \operatorname{SL}_2({\mathbb R}) |} \sum_{\tau \in \Gamma \backslash \mathcal{M}} \alpha(\tau)  \int_{\operatorname{SL}_2({\mathbb R})} F(g) \, \mathrm d g \bigg|  \ll_\varepsilon \delta^{-O(1)} Z^\varepsilon  \sqrt{ AD \, \mathcal{K} \, \mathcal{R}},
\end{align*}
where $Z = \max\{A^{\pm 1},C^{\pm 1},D^{\pm 1}\}$,
\begin{align*}
\mathcal{K}& = \sum_{\substack{g =\smqty(a & b \\mathfrak c & d) \in \mathcal{M}^{-1} \mathcal{M} \\  |a|+|b|C/D+|c|D/C+|d| \,\leq 6}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash \mathcal{M} 
 \\ \tau g \in \mathcal{M}}} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr|, \quad \quad\text{and} \\
\mathcal{R}& =    \left(1+ (AD)^{2\theta}\bigg( \frac{ C}{ A q_2}\bigg)^{2\theta} \right)\left(1+\bigg(\frac{C}{A q_2}\bigg)^{1-2\theta} \right) + \frac{A}{Cq_1}, \quad \theta=7/64.
\end{align*}

\begin{align*}
   \bigg|  \sum_{g \in \mathcal{M}}  \alpha(g) F(g)  -  \frac{1}{|\Gamma \backslash \operatorname{SL}_2({\mathbb R}) |} \sum_{\tau \in \Gamma \backslash \mathcal{M}} \alpha(\tau)  \int_{\operatorname{SL}_2({\mathbb R})} F(g) \, \mathrm d g \bigg|  \ll_\varepsilon \delta^{-O(1)} Z^\varepsilon  \sqrt{ AD \, \mathcal{K} \, \mathcal{R}},
\end{align*}

\begin{align*}
\mathcal{K}& = \sum_{\substack{g =\smqty(a & b \\mathfrak c & d) \in \mathcal{M}^{-1} \mathcal{M} \\  |a|+|b|C/D+|c|D/C+|d| \,\leq 6}}\Bigl|\sum_{ \substack{\tau\in \Gamma \backslash \mathcal{M} 
 \\ \tau g \in \mathcal{M}}} \alpha(\tau) \overline{\alpha(\tau g)} \Bigr|, \quad \quad\text{and} \\
\mathcal{R}& =    \left(1+ (AD)^{2\theta}\bigg( \frac{ C}{ A q_2}\bigg)^{2\theta} \right)\left(1+\bigg(\frac{C}{A q_2}\bigg)^{1-2\theta} \right) + \frac{A}{Cq_1}, \quad \theta=7/64.
\end{align*}

\begin{align*}
    \mathcal{R} \ll  1 + \frac{C}{A q_2} +\frac{A}{C q_1}.
\end{align*}

\begin{align*}
     \mathcal{K} \ll |\Gamma \backslash \mathcal{M}| + \frac{|\Gamma \backslash \mathcal{M}|^2}{q_1q_2},
 \end{align*}

\label{subsec:appli}
We obtain the following applications, which follow from a more technical version of Theorem \ref{thm:mainblackbox}, see Theorem \ref{thm:twisteddetwbound}. Theorem \ref{thm:mainblackbox} would suffice for these in the range $|h| \ll 1$.  For simplicity we restrict to the case of a square-free modulus $q$ and $\gcd(h,q)=1$, in the general case for some applications there may be additional losses depending on $q/\mathrm{rad}(q)$ and $\gcd(h,q^\infty)$.  

As a first application we consider a general statement concerning sums over $d(n)d(n+h)t(n)$, where $t(n)$ is a periodic function. Define for square-free $q$ and for $h,r\in {\mathbb Z}$  with $\gcd(h,q)=1$
\begin{align*}
    \omega(r,h;q) &:= \prod_{p| q}  \omega(r,h;p), \\
        \omega(r,h;p) &:= \begin{cases}
        \frac{p-1}{p(p+1)}, \quad  &\text{if } r(r+h) \not \equiv
        0 \pmod{q} \\
           \frac{2p-1}{p(p+1)}, \quad  &\text{if }  r(r+h) \equiv
        0 \pmod{q}
    \end{cases}
\end{align*}
and note that $r\mapsto   \omega(r,h;q)$ defines a probability measure on ${\mathbb Z}/q{\mathbb Z}$.

