 \label{thm:divisorperiodic}
    Let $h,q\in {\mathbb Z}$ with $q$ square-free and $\gcd(h,q)=1$. Let $X,\eta > 0$ and suppose that $-X/2\leq h  \leq X^{1+\eta}$.  Let $G:{\mathbb R}\to{\mathbb C}$ be a smooth  function supported on $[1,2]$ that satisfies $G^{(j)} \ll_j X^{j \eta }$ for all $j \geq 0$. Let $t:{\mathbb Z}/q{\mathbb Z} \to {\mathbb C}$ be a function. Then for some binary quadratic polynomial $P_h$, only depending on $h$, we have
    \begin{align*}
        \sum_{\substack{ n }} G(n/X) d(n) d(n+h)t(n) =&\sum_{r\pmod{q}} t(r)\omega(r,h;q) \int G(u/X)  P_h( \log u,\log(u+h)) \,\mathrm d u
        \\
        &\hspace{20pt}+O\bigg( X^{1/2+O(\eta)} q^{1/2}\|t\|_2   (|h|^{\theta}+(X/q)^{\theta})  \bigg),
    \end{align*}
where  $\|t\|_2^2 = \sum_{r \pmod{q}} |t(r)|^2$ and $\theta= 7/64$ denotes the best approximation to the Ramanujan-Peterson and Selberg eigenvalue conjectures.

\begin{align*}
        \sum_{\substack{ n }} G(n/X) d(n) d(n+h)t(n) =&\sum_{r\pmod{q}} t(r)\omega(r,h;q) \int G(u/X)  P_h( \log u,\log(u+h)) \,\mathrm d u
        \\
        &\hspace{20pt}+O\bigg( X^{1/2+O(\eta)} q^{1/2}\|t\|_2   (|h|^{\theta}+(X/q)^{\theta})  \bigg),
    \end{align*}

\begin{align}\label{eq:MTdivisorap}
    \mathrm{MT}_G(X,r,h,q)= \omega(r,h;q) \int G(u/X) P_h( \log u,\log(u+h)) \,\mathrm d u
\end{align}

 \label{cor:fixedap}
Assume the requirements of Theorem \ref{thm:divisorperiodic}, let $r\in {\mathbb Z}$ and $\mathrm{MT}_G(X,r,h,q)$ given by \eqref{eq:MTdivisorap}. Then we have
    \begin{align*}
        \sum_{\substack{ n\equiv r \pmod{q}}} G(n/X) d(n) d(n+h)=  \mathrm{MT}_G(X,r,h,q)+ O\bigg( X^{1/2+O(\eta)} q^{1/2}  (|h|^{\theta}+(X/q)^{\theta})  \bigg).
    \end{align*}

\begin{align*}
        \sum_{\substack{ n\equiv r \pmod{q}}} G(n/X) d(n) d(n+h)=  \mathrm{MT}_G(X,r,h,q)+ O\bigg( X^{1/2+O(\eta)} q^{1/2}  (|h|^{\theta}+(X/q)^{\theta})  \bigg).
    \end{align*}

\begin{align*}
   q & \leq X^{\frac{1-2\theta}{3-2\theta } - \varepsilon} , \quad \quad  |h| \leq X/q \\
  q  &\leq X^{1/3-\varepsilon} |h|^{ -2\theta/3} \quad \quad X/q < |h| \leq X^{1+\eta}.
\end{align*}

\begin{align*}
        \sum_{\substack{ n \leq X \\ n\equiv r \pmod{q}}}  d(n) d(n+h)=   \omega(r,h;q)  \int_1^X   P_h( \log u,\log(u+h)) \,\mathrm d u(1+O(X^{-\varepsilon'})).
    \end{align*}

\label{cor:averageap} Assume the requirements of Theorem \ref{thm:divisorperiodic} and let $ \mathrm{MT}_G(X,r,h,q)$ given by \eqref{eq:MTdivisorap}. Then we have
