For simplicity let us assume that $\Gamma= \Gamma_0(q)$. The general case is reduced to this by conjugation by $\mathrm{a}[q_1] = \smqty(\sqrt{q_1} & \\ & 1/\sqrt{q_1})$. Using the $\Gamma$-invariance of $\alpha$ we can write
\begin{align*}
    \sum_{g \in \mathcal{M}} \alpha(g) F(g) = \sum_{\tau \in \Gamma \backslash \mathcal{M}} \alpha(\tau) P_f(\tau), \quad \quad P_f(\tau):= \sum_{\gamma \in \Gamma} F(\gamma \tau).
\end{align*}
Here $P_f(\tau)$ is a type of Poincar\'e series on $\operatorname{SL}_2({\mathbb R})$, which is smooth and invariant under the left action by $\Gamma$.  Hence, applying the spectral expansion on $\Gamma \backslash \operatorname{SL}_2({\mathbb R})$ we get (omitting the continuous spectrum for brevity)
\begin{align*}
   P_f(\tau) = \frac{1}{|\Gamma \backslash \operatorname{SL}_2({\mathbb R})|} \langle P_f,1 \rangle_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} + \sum_{\varphi \in \mathcal{B}(q)} \langle P_f, \varphi \rangle_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} \varphi(\tau), 
\end{align*}
where $\mathcal{B}(q)$ denotes an orthonormal basis of automorphic forms on $\Gamma \backslash \operatorname{SL}_2({\mathbb R})$ and the inner product is given by
\begin{align*}
\langle f_1, f_2 \rangle_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} := \int_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} f_1(g) \overline{f_2}(g) \, \mathrm d g.
\end{align*}

\begin{align*}
    \sum_{g \in \mathcal{M}} \alpha(g) F(g) = \sum_{\tau \in \Gamma \backslash \mathcal{M}} \alpha(\tau) P_f(\tau), \quad \quad P_f(\tau):= \sum_{\gamma \in \Gamma} F(\gamma \tau).
\end{align*}

\begin{align*}
   P_f(\tau) = \frac{1}{|\Gamma \backslash \operatorname{SL}_2({\mathbb R})|} \langle P_f,1 \rangle_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} + \sum_{\varphi \in \mathcal{B}(q)} \langle P_f, \varphi \rangle_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} \varphi(\tau), 
\end{align*}

\begin{align*}
\langle f_1, f_2 \rangle_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} := \int_{\Gamma \backslash \operatorname{SL}_2({\mathbb R})} f_1(g) \overline{f_2}(g) \, \mathrm d g.
\end{align*}

\begin{align}\label{eq:introspecexp}
